files.content:
.divider{
  display:block;
  width:100%;
  height:0;
  margin:0;
  padding:0;
  border:0;
  border-top:var(--bw-1) solid var(--obsidian-700);
}
.divider-vertical{
  align-self:stretch;
  width:0;
  height:auto;
  min-height:var(--s-4);
  border-top:0;
  border-left:var(--bw-1) solid var(--obsidian-700);
}
.divider-label{
  display:flex;
  align-items:center;
  gap:var(--s-3);
  width:100%;
  color:var(--obsidian-300);
  font-size:var(--t-caption);
}
.divider-label::before, .divider-label::after{
  content:"";
  flex:1;
  border-top:var(--bw-1) solid var(--obsidian-700);
}
.divider-label){
  width:min(100%, calc(var(--s-32) * 2));
}
